for cid, obj in P.items():
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
print("written", len(P))
# self-verify
import glob
ok = 0
for cid in P:
    d = json.load(open(os.path.join(OUT, cid + ".json"), encoding="utf-8"))
    assert d["case_id"] == cid and set(["case_id","prediction_text","basis","confidence","trigger"]).issubset(d)
    assert 0 <= d["confidence"] <= 1
    assert set(d["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
    ok += 1
print("verified", ok)
cm = sum(v["trigger"]["changed_main"] for v in P.values()); ru = sum(v["trigger"]["reserve_used"] for v in P.values()); dp = sum(v["trigger"]["disputed"] for v in P.values())
print("trigger counts changed_main/reserve_used/disputed =", cm, ru, dp)
